"use strict";(self.webpackChunkwiki_es=self.webpackChunkwiki_es||[]).push([["87782"],{13280(e){e.exports=JSON.parse('{"categoryGeneratedIndex":{"title":"Documentos de desarrollo de software de reCamera","description":"La reCamera es un dispositivo listo para usar inmediatamente despu\xe9s del arranque. Viene con un sistema reCamera OS estable que admite actualizaciones de firmware OTA. Adem\xe1s, la plataforma de IA SenseCraft y Node-RED est\xe1n integrados en el dispositivo para ofrecer una experiencia de implementaci\xf3n m\xe1s sencilla. Esta integraci\xf3n ofrece a los desarrolladores principiantes una experiencia de programaci\xf3n modular basada en nodos de Node-RED. Para desarrolladores avanzados, tambi\xe9n est\xe1n disponibles el desarrollo profundo basado en Linux y Python para experimentar y personalizar. Damos una c\xe1lida bienvenida a los desarrolladores con experiencia en JavaScript, C/C++, Python, Linux OS, buildroot, as\xed como a entusiastas, estudiantes y principiantes, a participar en un desarrollo m\xe1s profundo y explorar aplicaciones.","slug":"recamera_software_docs","permalink":"/es/recamera_software_docs","sidebar":"esSidebar","navigation":{"previous":{"title":"Gu\xeda de inicio de Wifi Halow","permalink":"/es/wifi_halow_getting_started"},"next":{"title":"Control de versiones del SO","permalink":"/es/recamera_os_version_control"}}}}')}}]);